"""Ordinary local import example using generated bytes and an in-memory peer."""
import importlib.util
from pathlib import Path
import sys
from unittest.mock import patch

from infile_api import execute

spec = importlib.util.spec_from_file_location(
    'local_mysql_peer', Path(__file__).with_name('infile-memory-peer.py'))
peer = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = peer
spec.loader.exec_module(peer)


def drain(cursor):
    while cursor.nextset():
        cursor.fetchall()


def main():
    print('Local import from an application-owned stream')
    stream = peer.ObservedStream(b'generated account data\n')
    server = peer.MemoryPeer([[('infile', b'prepared')]])
    connection = server.connection()
    with patch('pymysql.connections.open',
               side_effect=AssertionError('A server name attempted a disk read'),
               create=True) as disk_open:
        cursor = connection.cursor()
        execute(cursor, 'LOAD DATA LOCAL application stream', {b'prepared': stream})
        drain(cursor)
        assert server.uploads == [{'name': b'prepared', 'data': b'generated account data\n'}]
        assert not stream.closed and not disk_open.called
        print('Transferred', len(server.uploads[0]['data']), 'generated bytes.')
        print('Caller still owns the open stream. Disk reads:', disk_open.call_count)

    print('\nServer asks for an unauthorized name during SELECT')
    server = peer.MemoryPeer([[('infile', b'not-authorized')]])
    connection = server.connection()
    with patch('pymysql.connections.open',
               side_effect=AssertionError('A server name attempted a disk read'),
               create=True) as disk_open:
        try:
            cursor = connection.cursor()
            execute(cursor, 'SELECT local generated value', {})
            drain(cursor)
        except Exception as error:
            print('Rejected with', type(error).__name__ + ':', str(error))
        else:
            raise AssertionError('Unauthorized import was accepted')
        assert not disk_open.called
        assert not any(item['data'] for item in server.uploads)
        print('Unauthorized bytes transferred: 0. Disk reads:', disk_open.call_count)

    print('\nOriginal SELECT remains available')
    server = peer.MemoryPeer([[('select', [b'local example'])]])
    connection = server.connection()
    cursor = connection.cursor()
    cursor.execute('SELECT local example')
    print('Rows:', cursor.fetchall())


if __name__ == '__main__':
    main()
